package gitignore

import (
	"strings"
)

// tokenKind identifies the type of a pattern token.
type tokenKind uint8

const (
	// tokenLiteral matches exactly one specific byte.
	tokenLiteral tokenKind = iota
	// tokenAnyByte matches any single byte other than a slash.
	tokenAnyByte
	// tokenClass matches any single byte in a table (which never includes a
	// slash).
	tokenClass
	// tokenStar matches zero or more bytes other than slashes.
	tokenStar
	// tokenAnyPath matches zero or more bytes of any kind, including slashes.
	// It is generated by a "**" that terminates a pattern.
	tokenAnyPath
	// tokenAnyDirectories begins a pair of tokens that match zero or more
	// complete directory components, including their trailing slashes. The pair
	// is generated by a "**/" and consumes the slash. The first token of the
	// pair matches nothing and either skips to the end of the pair or enters
	// the loop that is the second token of the pair.
	tokenAnyDirectories
	// tokenAnyDirectoriesLoop is the second token of the pair that begins with
	// tokenAnyDirectories. It matches any number of bytes, including slashes,
	// followed by a slash. Separating it from the first token ensures that the
	// option of matching zero directories can't be taken once the loop has
	// consumed input.
	tokenAnyDirectoriesLoop
)

// token is a single element of a compiled pattern.
type token struct {
	// kind is the token type.
	kind tokenKind
	// value is the byte matched by a literal token.
	value byte
	// class is the set of bytes matched by a class token.
	class *byteSet
}

// byteSet is a set of bytes, represented as a bitmap. It's the compiled form of
// a bracket expression, which has to be compact, since a rule file within the
// size limit can contain millions of them.
type byteSet [4]uint64

// add adds a byte to the set.
func (s *byteSet) add(b byte) {
	s[b>>6] |= 1 << (b & 63)
}

// remove removes a byte from the set.
func (s *byteSet) remove(b byte) {
	s[b>>6] &^= 1 << (b & 63)
}

// contains returns true if a byte is a member of the set.
func (s *byteSet) contains(b byte) bool {
	return s[b>>6]&(1<<(b&63)) != 0
}

// newByteSet creates a set of the bytes for which a function returns true.
func newByteSet(member func(byte) bool) byteSet {
	var set byteSet
	for b := 0; b < 256; b++ {
		if member(byte(b)) {
			set.add(byte(b))
		}
	}
	return set
}

// posixClasses maps the names of POSIX character classes to their members.
// Only ASCII bytes are ever members of a class. The classes are those of Git's
// own character table rather than those of the C library, which only makes a
// difference for "space": Git's excludes the vertical tab and the form feed.
var posixClasses = map[string]byteSet{
	"alnum":  newByteSet(func(b byte) bool { return isAlpha(b) || isDigit(b) }),
	"alpha":  newByteSet(isAlpha),
	"blank":  newByteSet(func(b byte) bool { return b == ' ' || b == '\t' }),
	"cntrl":  newByteSet(func(b byte) bool { return b < 32 || b == 127 }),
	"digit":  newByteSet(isDigit),
	"graph":  newByteSet(func(b byte) bool { return b > 32 && b < 127 }),
	"lower":  newByteSet(func(b byte) bool { return b >= 'a' && b <= 'z' }),
	"print":  newByteSet(func(b byte) bool { return b >= 32 && b < 127 }),
	"punct":  newByteSet(func(b byte) bool { return b > 32 && b < 127 && !isAlpha(b) && !isDigit(b) }),
	"space":  newByteSet(func(b byte) bool { return b == ' ' || b == '\t' || b == '\n' || b == '\r' }),
	"upper":  newByteSet(func(b byte) bool { return b >= 'A' && b <= 'Z' }),
	"xdigit": newByteSet(func(b byte) bool { return isDigit(b) || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F') }),
}

// isAlpha returns true if the byte is an ASCII letter.
func isAlpha(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// isDigit returns true if the byte is an ASCII digit.
func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

// addRange adds the bytes from low to high (inclusive) to the set, a word at a
// time. If high is less than low, then it adds nothing.
func (s *byteSet) addRange(low, high byte) {
	for b := int(low); b <= int(high); b = (b | 63) + 1 {
		last := 63
		if int(high)>>6 == b>>6 {
			last = int(high) & 63
		}
		s[b>>6] |= (^uint64(0) << (b & 63)) & (^uint64(0) >> (63 - last))
	}
}

// parseClass parses the bracket expression that begins at pattern[start],
// which must be an opening bracket. It returns the set of bytes that the
// expression matches, as well as the index of the first byte following the
// expression. If the expression is unterminated or names an unknown POSIX
// class, then parseClass returns false, in which case the pattern containing
// the expression can never match anything.
//
// The syntax is the one documented for fnmatch(3) bracket expressions: an
// optional leading "!" or "^" negates the expression, a "]" that comes first
// is a literal member, "a-c" denotes a range, a "-" that comes first or last
// is a literal member, a backslash makes the next byte a literal member, and
// "[:name:]" denotes a POSIX character class. A bracket expression never
// matches a slash. A range with reversed bounds, such as "c-a", contains no
// bytes other than its lower bound, which is a member like any other.
func parseClass(pattern string, start int) (*byteSet, int, bool) {
	var parser classParser
	return parser.parse(pattern, start)
}

// classParser implements parseClass. Parsing takes time proportional to the
// length of the expression, because each byte is examined a bounded number of
// times, which matters because rules are parsed by every scan and a rule file
// can be large.
type classParser struct {
	// closing is the index of the closing bracket that the last search for
	// one found (see parse), or zero if there hasn't been a search.
	closing int
	// searched is the number of bytes that searches for closing brackets have
	// examined, which never exceeds the length of the pattern.
	searched int
}

// parse implements parseClass.
func (p *classParser) parse(pattern string, start int) (*byteSet, int, bool) {
	// Skip the opening bracket and check for negation.
	index := start + 1
	var negated bool
	if index < len(pattern) && (pattern[index] == '!' || pattern[index] == '^') {
		negated = true
		index++
	}

	// Accumulate members until we reach the closing bracket.
	members := new(byteSet)
	first := true
	for {
		// If we've run out of pattern, then the expression is unterminated.
		if index >= len(pattern) {
			return nil, 0, false
		}

		// A closing bracket terminates the expression, unless it's the first
		// member, in which case it's a literal.
		current := pattern[index]
		if current == ']' && !first {
			index++
			break
		}
		first = false

		// Determine the member (or the lower bound of a range) that begins
		// here.
		var low byte
		switch {
		case current == '[' && index+1 < len(pattern) && pattern[index+1] == ':':
			// Find the end of what might be a POSIX class name, which is the
			// next closing bracket. If there isn't one, then the expression is
			// unterminated. If the text up to it doesn't end with a colon, then
			// this isn't a class name and the opening bracket is just a literal
			// member. A closing bracket that an earlier search found beyond
			// this point is the next one, since that search examined what's in
			// between, so we only search again once we've passed it, which
			// keeps parsing linear when an expression contains many "[:" that
			// don't begin class names.
			if p.closing < index+2 {
				end := strings.IndexByte(pattern[index+2:], ']')
				if end < 0 {
					p.searched += len(pattern) - (index + 2)
					return nil, 0, false
				}
				p.searched += end + 1
				p.closing = index + 2 + end
			}
			name := pattern[index+2 : p.closing]
			if len(name) > 0 && name[len(name)-1] == ':' {
				class, ok := posixClasses[name[:len(name)-1]]
				if !ok {
					return nil, 0, false
				}
				for w := range members {
					members[w] |= class[w]
				}
				index = p.closing + 1
				continue
			}
			low = current
			index++
		case current == '\\':
			if index+1 >= len(pattern) {
				return nil, 0, false
			}
			low = pattern[index+1]
			index += 2
		default:
			low = current
			index++
		}

		// Check whether this member is the lower bound of a range. A hyphen
		// that precedes the closing bracket is a literal member instead.
		if index+1 < len(pattern) && pattern[index] == '-' && pattern[index+1] != ']' {
			var high byte
			if pattern[index+1] == '\\' {
				if index+2 >= len(pattern) {
					return nil, 0, false
				}
				high = pattern[index+2]
				index += 3
			} else {
				high = pattern[index+1]
				index += 2
			}
			members.addRange(low, high)
		}
		members.add(low)
	}

	// Apply negation and ensure that slashes never match.
	if negated {
		for w := range members {
			members[w] = ^members[w]
		}
	}
	members.remove('/')

	// Success.
	return members, index, true
}

// matcher matches compiled patterns against text. It simulates a
// nondeterministic automaton by tracking the set of tokens that could match
// next, so matching takes time proportional to the product of the number of
// tokens and the length of the text, regardless of how many wildcards a
// pattern contains. A matcher retains its working storage between uses, which
// avoids allocation, but it is not safe for concurrent use.
type matcher struct {
	// current is the set of states being processed in the current step.
	current []int
	// next is the set of states being assembled for the next step.
	next []int
	// marks records, for each state, the generation in which it was last added
	// to next. It prevents states from being added more than once.
	marks []uint32
	// generation is the current mark generation.
	generation uint32
	// accepted indicates whether or not the end of the pattern has been
	// reached in the set that's being assembled.
	accepted bool
}

// begin starts a new generation of marks.
func (m *matcher) begin() {
	m.generation++
	if m.generation == 0 {
		clear(m.marks[:cap(m.marks)])
		m.generation = 1
	}
	m.accepted = false
}

// add adds a state to the set being assembled, along with every state that can
// be reached from it without consuming input. The state with an index equal to
// the number of tokens is the accepting state.
func (m *matcher) add(tokens []token, state int) {
	for {
		if m.marks[state] == m.generation {
			return
		}
		m.marks[state] = m.generation
		if state == len(tokens) {
			m.accepted = true
			return
		}
		m.next = append(m.next, state)
		switch tokens[state].kind {
		case tokenStar, tokenAnyPath:
			// These tokens can match nothing, so we can advance past them.
			state++
		case tokenAnyDirectories:
			// Either skip the loop or enter it.
			m.add(tokens, state+2)
			state++
		default:
			return
		}
	}
}

// matches returns true if the tokens match all of the text.
func (m *matcher) matches(tokens []token, text string) bool {
	// Ensure that we have enough storage for the marks. Marks that survive
	// from an earlier use always belong to an earlier generation, so growing
	// or truncating the slice can't cause a stale mark to be mistaken for a
	// current one.
	if cap(m.marks) <= len(tokens) {
		m.marks = make([]uint32, len(tokens)+16)
	}
	m.marks = m.marks[:len(tokens)+1]

	// Start with the states that are reachable before any input is consumed.
	m.next = m.next[:0]
	m.begin()
	m.add(tokens, 0)

	// Consume the text one byte at a time.
	for i := 0; i < len(text); i++ {
		// If no states remain, then there's no way to continue matching.
		if len(m.next) == 0 {
			return false
		}

		// Move to the next step.
		m.current, m.next = m.next, m.current[:0]
		m.begin()
		b := text[i]
		for _, state := range m.current {
			switch tokens[state].kind {
			case tokenLiteral:
				if b == tokens[state].value {
					m.add(tokens, state+1)
				}
			case tokenAnyByte:
				if b != '/' {
					m.add(tokens, state+1)
				}
			case tokenClass:
				if tokens[state].class.contains(b) {
					m.add(tokens, state+1)
				}
			case tokenStar:
				if b != '/' {
					m.add(tokens, state)
				}
			case tokenAnyPath:
				m.add(tokens, state)
			case tokenAnyDirectoriesLoop:
				m.add(tokens, state)
				if b == '/' {
					m.add(tokens, state+1)
				}
			}
		}
	}

	// The text matches if the end of the pattern was reached.
	return m.accepted
}
